package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.InjectableValues;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws IOException
  {
    ObjectMapper mapper = new DefaultObjectMapper();
    // Simulate the server environment where JavaScriptConfig is disabled by default
    mapper.setInjectableValues(new InjectableValues.Std().addValue(JavaScriptConfig.class, new JavaScriptConfig(false)));

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"function\": \"function(x) { return true; }\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    try {
      DimFilter filter = mapper.readValue(json, DimFilter.class);
      // If we get here, deserialization succeeded.
      // Now check if we can get the predicate factory, which checks if JS is enabled.
      if (filter instanceof JavaScriptDimFilter) {
          try {
            // This method calls config.isEnabled()
             filter.toFilter();
             Assert.fail("Should have thrown exception because JS is disabled in injected config");
          } catch (IllegalStateException e) {
              if ("JavaScript is disabled".equals(e.getMessage())) {
                  System.out.println("Exploit failed: JavaScript is correctly disabled.");
              } else {
                  throw e;
              }
          }
      }
    } catch (Exception e) {
      e.printStackTrace();
    }
  }
}

